CREATE SEQUENCE authors_id_seq START 1;
CREATE SEQUENCE books_id_seq;

CREATE TYPE genre AS ENUM ('fiction', 'science', 'history');

CREATE TABLE authors (
  id          INTEGER PRIMARY KEY DEFAULT nextval('authors_id_seq'),
  name        VARCHAR NOT NULL,
  bio         TEXT,
  email       VARCHAR UNIQUE,
  born        DATE,
  rating      DECIMAL(3,1),
  tags        VARCHAR[] NOT NULL DEFAULT [],
  meta        JSON,
  external_id UUID,
  active      BOOLEAN NOT NULL DEFAULT true,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ
);

CREATE TABLE books (
  id         BIGINT PRIMARY KEY DEFAULT nextval('books_id_seq'),
  author_id  INTEGER NOT NULL REFERENCES authors(id),
  title      VARCHAR NOT NULL,
  genre      genre NOT NULL,
  pages      INTEGER,
  price      DECIMAL(10,2) NOT NULL,
  weight     DOUBLE,
  isbn       UUID NOT NULL,
  published  DATE,
  scores     INTEGER[],
  extra      JSON NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX books_author_idx ON books (author_id);

-- Every mapped type, NOT NULL and nullable.
CREATE TABLE samples (
  id     INTEGER PRIMARY KEY,
  b      BOOLEAN NOT NULL,
  nb     BOOLEAN,
  i1     TINYINT NOT NULL,
  ni1    TINYINT,
  i2     SMALLINT NOT NULL,
  ni2    SMALLINT,
  i4     INTEGER NOT NULL,
  ni4    INTEGER,
  i8     BIGINT NOT NULL,
  ni8    BIGINT,
  u1     UTINYINT NOT NULL,
  nu1    UTINYINT,
  u2     USMALLINT NOT NULL,
  nu2    USMALLINT,
  u4     UINTEGER NOT NULL,
  nu4    UINTEGER,
  u8     UBIGINT NOT NULL,
  nu8    UBIGINT,
  h      HUGEINT NOT NULL,
  nh     HUGEINT,
  uh     UHUGEINT NOT NULL,
  nuh    UHUGEINT,
  f4     FLOAT NOT NULL,
  nf4    FLOAT,
  f8     DOUBLE NOT NULL,
  nf8    DOUBLE,
  d      DECIMAL(18,4) NOT NULL,
  nd     DECIMAL(18,4),
  s      VARCHAR NOT NULL,
  ns     VARCHAR,
  t      TEXT NOT NULL,
  nt     TEXT,
  bl     BLOB NOT NULL,
  nbl    BLOB,
  dt     DATE NOT NULL,
  ndt    DATE,
  tm     TIME NOT NULL,
  ntm    TIME,
  ts     TIMESTAMP NOT NULL,
  nts    TIMESTAMP,
  tstz   TIMESTAMPTZ NOT NULL,
  ntstz  TIMESTAMPTZ,
  iv     INTERVAL NOT NULL,
  niv    INTERVAL,
  u      UUID NOT NULL,
  nu     UUID,
  j      JSON NOT NULL,
  nj     JSON,
  g      genre NOT NULL,
  ng     genre,
  e      ENUM('x', 'y') NOT NULL,
  ne     ENUM('x', 'y'),
  li     INTEGER[] NOT NULL,
  nli    INTEGER[],
  ls     VARCHAR[] NOT NULL,
  nls    VARCHAR[],
  lu     UUID[] NOT NULL,
  nlu    UUID[],
  lj     JSON[] NOT NULL,
  nlj    JSON[],
  fixed  INTEGER[3] NOT NULL,
  nfixed INTEGER[3],
  st     STRUCT(a INTEGER, b VARCHAR) NOT NULL,
  nst    STRUCT(a INTEGER, b VARCHAR),
  m      MAP(VARCHAR, INTEGER) NOT NULL,
  nm     MAP(VARCHAR, INTEGER)
);
